CREATE OR REPLACE FUNCTION trip_private.inspiration_validate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' THEN IF NEW.trip_id<>OLD.trip_id OR NEW.creator_id<>OLD.creator_id OR NEW.partner_id IS DISTINCT FROM OLD.partner_id OR NEW.hidden_at IS DISTINCT FROM OLD.hidden_at OR NEW.mode<>OLD.mode OR NEW.votes_revealed_at IS DISTINCT FROM OLD.votes_revealed_at THEN RAISE EXCEPTION 'Experience ownership and results cannot be changed'; END IF; END IF; IF NEW.partner_id IS NOT NULL AND NOT trip_private.is_trip_member(NEW.trip_id,NEW.partner_id) THEN RAISE EXCEPTION 'Partner must be in the squad'; END IF; IF NEW.photo_path IS NOT NULL AND (split_part(NEW.photo_path,'/',1)<>NEW.id::text OR NEW.photo_path !~* '\.(jpe?g|png|webp)$') THEN RAISE EXCEPTION 'Invalid photo path'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION trip_private.inspiration_vote_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.card_id<>OLD.card_id OR NEW.voter_id<>OLD.voter_id THEN RAISE EXCEPTION 'Ballot cannot be reassigned'; END IF; RETURN NEW; END $$;
CREATE TRIGGER inspiration_vote_validate BEFORE UPDATE ON public.inspiration_votes FOR EACH ROW EXECUTE FUNCTION trip_private.inspiration_vote_validate();
REVOKE ALL ON FUNCTION trip_private.inspiration_vote_validate() FROM PUBLIC,anon;